// Package db is the database runtime that code generated by the Alder
// compiler imports: one Table descriptor per `table` declaration, Select
// values built by Db.from/where/orderBy/limit/offset, the Store interface
// the effect steps call, and its SQLite implementation.
//
// Storage mapping (one SQL column per field, in declaration order):
//
//	Text, brands of Text   TEXT
//	Int                    INTEGER
//	Float                  REAL
//	Bool                   INTEGER 0 or 1
//	Date                   TEXT "YYYY-MM-DD"
//	Time                   TEXT, RFC 3339 with nanoseconds, always UTC ("…Z")
//	payload-less union     TEXT, the constructor name
//	Maybe T                T's column, NULL for Nothing
//
// The SQL table name is the module-qualified Alder table name with "." →
// "__" ("Todo.Todo" → "Todo__Todo"). Every identifier in generated SQL is a
// double-quoted name taken from a descriptor; every value is a `?`
// placeholder argument, so no user data is ever spliced into SQL text.
package db

import (
	"strconv"
	"strings"
)

// ColType is a column's storage type.
type ColType int

const (
	CText  ColType = iota // TEXT (Text and its brands)
	CInt                  // INTEGER
	CFloat                // REAL
	CBool                 // INTEGER 0/1
	CDate                 // TEXT YYYY-MM-DD
	CTime                 // TEXT RFC 3339 nanoseconds, UTC
	CEnum                 // TEXT constructor name; orders by declaration
)

// Column describes one field of a table.
type Column struct {
	Name     string
	Type     ColType
	Nullable bool     // Maybe T
	Enum     []string // CEnum: constructor names in declaration order
	Unique   bool
	Ref      string // table name for @ref (module-qualified, like Table.Name), "" otherwise
}

// Table describes one `table`. Generated code builds one per table as a package var.
//
// Insert values: the record without id/created/updated; generated code
// passes the column values in Columns order with nil at those three
// positions.
type Table[T any] struct {
	Name    string   // "Todo" (module-qualified: "Todo.Todo" → SQL table "Todo__Todo")
	Columns []Column // in declaration order, including the id column
	ID      string   // the @id column
	Created string   // @created column or ""
	Updated string   // @updated column or ""
	Encode  func(T) []any
	Decode  func([]any) (T, error)
	ReadID  func(T) string
	SetID   func(T, string) T
}

// TableDesc is a Table without its Go type, for Ensure.
type TableDesc struct {
	Name    string
	Columns []Column
	ID      string
	Created string
	Updated string
}

// Desc is t without its Go type.
func (t *Table[T]) Desc() TableDesc {
	return TableDesc{Name: t.Name, Columns: t.Columns, ID: t.ID, Created: t.Created, Updated: t.Updated}
}

// SQLName is the SQL table name for an Alder table name: "." → "__".
func SQLName(table string) string { return strings.ReplaceAll(table, ".", "__") }

// quote makes a double-quoted SQL identifier.
func quote(name string) string { return `"` + strings.ReplaceAll(name, `"`, `""`) + `"` }

// literal makes a single-quoted SQL string literal (used only for enum
// constructor names, which come from descriptors).
func literal(s string) string { return `'` + strings.ReplaceAll(s, `'`, `''`) + `'` }

// Select is data; the store turns it into SQL. Build one with From and the
// functions below; they never modify their argument.
type Select[T any] struct {
	Table  *Table[T]
	Where  []Cond
	Order  []Order
	Limit  *int64
	Offset *int64
}

// CondKind is the kind of a Cond.
type CondKind int

const (
	Eq CondKind = iota
	Ne
	Lt
	Le
	Gt
	Ge
	Contains
	In
	IsNull
	IsNotNull
	And
	Or
	Not
)

// Cond is one condition. Val is an encoded scalar (see encode.go), or []any
// for In; Subs holds the operands of And/Or/Not.
type Cond struct {
	Kind CondKind
	Col  string
	Val  any
	Subs []Cond
}

// Order is one ORDER BY term.
type Order struct {
	Col  string
	Desc bool
}

// From is Db.from: every row of t.
func From[T any](t *Table[T]) Select[T] { return Select[T]{Table: t} }

// Where is Db.where; several are combined with AND.
func Where[T any](c Cond, s Select[T]) Select[T] {
	s.Where = append(append([]Cond(nil), s.Where...), c)
	return s
}

// OrderBy is Db.orderBy; earlier calls take precedence.
func OrderBy[T any](o Order, s Select[T]) Select[T] {
	s.Order = append(append([]Order(nil), s.Order...), o)
	return s
}

// Limit is Db.limit.
func Limit[T any](n int64, s Select[T]) Select[T] { s.Limit = &n; return s }

// Offset is Db.offset.
func Offset[T any](n int64, s Select[T]) Select[T] { s.Offset = &n; return s }

func CEq(col string, v any) Cond       { return Cond{Kind: Eq, Col: col, Val: v} }
func CNe(col string, v any) Cond       { return Cond{Kind: Ne, Col: col, Val: v} }
func CLt(col string, v any) Cond       { return Cond{Kind: Lt, Col: col, Val: v} }
func CLe(col string, v any) Cond       { return Cond{Kind: Le, Col: col, Val: v} }
func CGt(col string, v any) Cond       { return Cond{Kind: Gt, Col: col, Val: v} }
func CGe(col string, v any) Cond       { return Cond{Kind: Ge, Col: col, Val: v} }
func CContains(col string, v any) Cond { return Cond{Kind: Contains, Col: col, Val: v} }
func CIn(col string, vs []any) Cond    { return Cond{Kind: In, Col: col, Val: vs} }
func CIsNull(col string) Cond          { return Cond{Kind: IsNull, Col: col} }
func CIsNotNull(col string) Cond       { return Cond{Kind: IsNotNull, Col: col} }
func CAnd(cs []Cond) Cond              { return Cond{Kind: And, Subs: cs} }
func COr(cs []Cond) Cond               { return Cond{Kind: Or, Subs: cs} }
func CNot(c Cond) Cond                 { return Cond{Kind: Not, Subs: []Cond{c}} }

func Asc(col string) Order  { return Order{Col: col} }
func Desc(col string) Order { return Order{Col: col, Desc: true} }

// SQL is a Select rendered for a store: Where is a boolean expression ("" for
// none) with `?` placeholders for Args; Order is the ORDER BY list without
// the keyword ("" for none); Limit/Offset are nil when not set.
type SQL struct {
	Where         string
	Args          []any
	Order         string
	Limit, Offset *int64
}

// SQL renders s. Column names are quoted; Eq/Ne with a nil value become IS
// NULL / IS NOT NULL, and Ne is null-safe (IS NOT ?), so Nothing ≠ Just x;
// Contains is `lower(col) LIKE lower(?) ESCAPE '\'` with % _ \ in the value
// escaped; In with no values is `0=1`; And/Or of nothing is `1=1`/`0=1`;
// every And, Or and Not is parenthesized. Several Where conditions render as
// one And. Ordering by an enum column orders by declaration (a CASE over its
// constructors).
func (s Select[T]) SQL() SQL {
	var out SQL
	switch len(s.Where) {
	case 0:
	case 1:
		out.Where = renderCond(s.Where[0], &out.Args)
	default:
		out.Where = renderCond(CAnd(s.Where), &out.Args)
	}
	var cols []Column
	if s.Table != nil {
		cols = s.Table.Columns
	}
	terms := make([]string, len(s.Order))
	for i, o := range s.Order {
		expr := quote(o.Col)
		for _, c := range cols {
			if c.Name == o.Col && c.Type == CEnum && len(c.Enum) > 0 {
				var b strings.Builder
				b.WriteString("CASE " + expr)
				for j, name := range c.Enum {
					b.WriteString(" WHEN " + literal(name) + " THEN " + strconv.Itoa(j))
				}
				b.WriteString(" END")
				expr = b.String()
			}
		}
		if o.Desc {
			terms[i] = expr + " DESC"
		} else {
			terms[i] = expr + " ASC"
		}
	}
	out.Order = strings.Join(terms, ", ")
	out.Limit, out.Offset = s.Limit, s.Offset
	return out
}

func renderCond(c Cond, args *[]any) string {
	col := quote(c.Col)
	bin := func(op string) string {
		*args = append(*args, c.Val)
		return col + " " + op + " ?"
	}
	switch c.Kind {
	case Eq:
		if c.Val == nil {
			return col + " IS NULL"
		}
		return bin("=")
	case Ne:
		if c.Val == nil {
			return col + " IS NOT NULL"
		}
		return bin("IS NOT")
	case Lt:
		return bin("<")
	case Le:
		return bin("<=")
	case Gt:
		return bin(">")
	case Ge:
		return bin(">=")
	case Contains:
		s, ok := c.Val.(string)
		if !ok {
			return "0=1" // only Text columns have .contains
		}
		*args = append(*args, "%"+escapeLike(s)+"%")
		return "lower(" + col + `) LIKE lower(?) ESCAPE '\'`
	case In:
		vs, _ := c.Val.([]any)
		if len(vs) == 0 {
			return "0=1"
		}
		*args = append(*args, vs...)
		return col + " IN (" + strings.TrimSuffix(strings.Repeat("?, ", len(vs)), ", ") + ")"
	case IsNull:
		return col + " IS NULL"
	case IsNotNull:
		return col + " IS NOT NULL"
	case And, Or:
		if len(c.Subs) == 0 {
			if c.Kind == And {
				return "1=1"
			}
			return "0=1"
		}
		op := " AND "
		if c.Kind == Or {
			op = " OR "
		}
		parts := make([]string, len(c.Subs))
		for i, sub := range c.Subs {
			parts[i] = renderCond(sub, args)
		}
		return "(" + strings.Join(parts, op) + ")"
	case Not:
		if len(c.Subs) != 1 {
			return "0=1"
		}
		return "NOT (" + renderCond(c.Subs[0], args) + ")"
	}
	return "0=1" // unknown kind: match nothing
}

func escapeLike(s string) string {
	return strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(s)
}
